INSERT INTO `lm_tickets` (`ticket_no`, `subject`, `requester`, `agent`, `priority`, `status`, `category`, `created`, `sla_hours`, `message`, `reply`, `resolution`, `satisfaction`) VALUES
('TCK-1012', 'Dashboard numbers differ from the report', 'Robert Klein', 'Jonas Weber', 3, 4, 'How-to', '2026-08-14 15:25:00', 24, 'The dashboard says 480 orders, the monthly report says 476.', 'The dashboard counts cancelled orders until midnight; the report only counts completed ones.', 'Explained the counting difference.', 4),
('TCK-1013', 'Add keyboard shortcuts', 'Elif Kaya', 'Amara Singh', 4, 4, 'Feature request', '2026-08-18 11:47:00', 72, 'Shortcuts for save and search would speed up my daily work.', 'Added to the wish list. Currently Ctrl+S saves any open form.', 'Logged as a feature request.', NULL),
('TCK-1014', 'Seat count does not match my team', 'Michael Brandt', 'Chloe Martin', 3, 3, 'Licensing', '2026-08-20 14:33:00', 24, 'The account says 12 seats but we only have 9 people.', 'Three former colleagues were still active. I disabled them and the seat count is now 9.', 'Deactivated 3 stale users; seat count corrected.', 4),
('TCK-1015', 'Bulk edit deletes selected rows', 'Fatima Zahra', 'Ben Carter', 2, 4, 'Bug', '2026-08-22 09:17:00', 8, 'Using bulk edit on 50 rows removed them instead of updating.', 'We found a wrong confirmation label. Data restored from the nightly backup and the label fixed.', 'Restored 50 rows from backup; fixed the confusing action label.', 3),
('TCK-1016', 'Need an invoice in Spanish', 'Carlos Ibáñez', 'Laura Vidal', 4, 4, 'Billing', '2026-08-25 12:01:00', 48, 'Our tax office asks for invoices in Spanish.', 'Set the account language to Spanish under Settings and re-download the invoice.', 'Language switch explained; invoice regenerated.', 5),
('TCK-1017', 'Webhook retries flood our server', 'Anna Kowalska', 'Jonas Weber', 1, 3, 'Bug', '2026-08-27 18:44:00', 4, 'The webhook is being sent hundreds of times for the same order.', 'Our retry loop did not stop after your 200 responses. We deployed a hotfix within the hour.', 'Hotfix deployed; retries stop after the first acknowledgement.', 5),
('TCK-1018', 'Account locked after too many attempts', 'Viktor Sokolov', 'Chloe Martin', 2, 3, 'Account', '2026-08-29 08:35:00', 8, 'I was locked out after typing the wrong password.', 'Locks last 15 minutes. I released it manually and sent a reset link.', 'Lock released manually; reset link sent.', 5),
('TCK-1019', 'Can I white-label the customer portal?', 'Priyanka Desai', 'Amara Singh', 4, 4, 'Feature request', '2026-08-31 16:12:00', 72, 'We want our own logo and colours instead of yours.', 'Logo and colours are available on the Pro plan under Settings > Branding.', 'Explained branding options on the Pro plan.', 4),
('TCK-1020', 'Export to PDF cuts off the last column', 'Sean O\'Brien', 'Ben Carter', 3, 3, 'Bug', '2026-09-01 10:28:00', 24, 'The PDF export loses the right-most column when the list is wide.', 'Fixed in this week\'s maintenance release. Wide lists now switch to landscape.', 'Fixed by switching wide exports to landscape orientation.', 5),
('TCK-1021', 'Refund for unused annual plan', 'Yuki Tanaka', 'Laura Vidal', 3, 4, 'Billing', '2026-09-02 13:50:00', 24, 'We closed the shop and would like a refund for the unused months.', 'Refunds are possible within 30 days of renewal. Your renewal was 41 days ago, so we offered a credit note instead.', 'Credit note issued; customer accepted.', 2),
('TCK-1022', 'Broken link in the welcome email', 'Mateo Alvarez', 'Jonas Weber', 4, 3, 'Bug', '2026-09-03 09:03:00', 48, 'The Getting started link in the welcome mail leads to a 404.', 'Thanks for reporting. The link pointed to a page we renamed; it is fixed for new mails.', 'Corrected the link in the email template.', 4),
('TCK-1023', 'Domain mismatch after site migration', 'Lena Fischer', 'Chloe Martin', 3, 2, 'Licensing', '2026-09-04 15:16:00', 24, 'After moving to a new host the license page shows a domain mismatch warning.', 'Please clear the cache and send the URL shown on the license page. We will update it on our side.', '', NULL),
('TCK-1024', 'Where can I download old invoices?', 'George Mitchell', 'Laura Vidal', 4, 4, 'How-to', '2026-09-05 11:22:00', 48, 'I cannot find invoices from last year.', 'Account > Billing > History lists everything, and each row has a PDF button.', 'Pointed to the billing history page.', 5),
('TCK-1025', 'Two-factor codes not accepted', 'Nina Petrova', 'Ben Carter', 2, 3, 'Account', '2026-09-07 07:58:00', 8, 'The authenticator codes are rejected even though my phone shows a new one.', 'The clock on the phone was 2 minutes off. Syncing the time fixed it.', 'Advised to enable automatic time on the phone; login works.', 5),
('TCK-1026', 'Add VAT ID field to checkout', 'Rafael Souza', 'Amara Singh', 3, 1, 'Feature request', '2026-09-08 09:40:00', 72, 'EU business customers need to enter a VAT ID at checkout.', 'Planned for the next release. I will notify you when it ships.', '', NULL),
('TCK-1027', 'Import fails for CSV with 5,000 rows', 'Camille Dubois', 'Jonas Weber', 2, 3, 'Bug', '2026-09-08 14:05:00', 8, 'The import stops at about 2,000 rows with a timeout.', 'We raised the timeout and the batch size. Please retry and tell us if it completes.', 'Import limits raised; customer imported 5,000 rows successfully.', 4),
('TCK-1028', 'License renewal reminder was not received', 'Henrik Larsen', 'Chloe Martin', 4, 4, 'Licensing', '2026-09-09 12:10:00', 48, 'Our key expired and nobody warned us.', 'The reminder went to a former employee\'s address. I updated the billing contact and extended the key by 7 days.', 'Billing contact updated and key extended.', 3),
('TCK-1029', 'Site is very slow since Monday', 'Aisha Rahman', 'Ben Carter', 1, 3, 'Bug', '2026-09-10 08:47:00', 4, 'Pages take 12 seconds to load. It started on Monday evening.', 'A runaway scheduled task was hammering the database. We disabled it and cleared the queue.', 'Root cause: a stuck scheduled task. Removed it and added a monitoring alert.', 5),
('TCK-1030', 'Upgrade my plan mid-cycle', 'Tomasz Nowak', 'Laura Vidal', 3, 3, 'Billing', '2026-09-11 16:30:00', 24, 'Can I move from Basic to Pro now and pay only the difference?', 'Yes, the difference is prorated. I upgraded the plan and sent the updated invoice.', 'Plan upgraded with prorated charge.', 4),
('TCK-1031', 'How to add a second admin user', 'Grace Kimani', 'Amara Singh', 4, 4, 'How-to', '2026-09-12 10:55:00', 48, 'I would like a colleague to manage users too. What are the steps?', 'Users > Add user, choose the Administrator role and send the invitation.', 'Answered with step-by-step instructions; no further questions.', 5),
('TCK-1032', 'Newsletter template breaks in Outlook', 'Luca Bianchi', 'Jonas Weber', 3, 2, 'Bug', '2026-09-14 13:40:00', 24, 'The header image is stretched in Outlook 2019. Other clients look fine.', 'Could you send a screenshot and the exact Outlook build? We suspect the image width attribute.', '', NULL),
('TCK-1033', 'Change the account owner', 'Emma Johansson', 'Chloe Martin', 3, 3, 'Account', '2026-09-15 09:12:00', 24, 'Our CEO left. Please make me the new account owner.', 'I need a written confirmation from the previous owner or a company registry extract.', 'Ownership transferred after receiving the signed confirmation.', 5),
('TCK-1034', 'Search returns no results for exact titles', 'David Okoye', 'Ben Carter', 2, 1, 'Bug', '2026-09-15 15:22:00', 8, 'Typing the full title of an existing article finds nothing, partial words work.', 'We can reproduce it with titles that contain a colon. Developers are working on the fix.', '', NULL),
('TCK-1035', 'Duplicate charge on my card', 'Isabelle Fournier', 'Laura Vidal', 1, 3, 'Billing', '2026-09-16 11:05:00', 4, 'I was charged twice for the September renewal.', 'Confirmed: the payment provider retried a timed-out charge. The duplicate has been refunded.', 'Refunded the duplicate charge (3-5 days to appear on the card statement).', 4),
('TCK-1036', 'Request: dark mode for the dashboard', 'Kenji Watanabe', 'Amara Singh', 4, 1, 'Feature request', '2026-09-16 17:48:00', 72, 'Our team works late. A dark theme for the dashboard would be great.', 'Thanks, this is a popular request. I added your vote to the item on the roadmap.', '', NULL);
INSERT INTO `lm_tickets` (`ticket_no`, `subject`, `requester`, `agent`, `priority`, `status`, `category`, `created`, `sla_hours`, `message`, `reply`, `resolution`, `satisfaction`) VALUES
('TCK-1037', 'License key rejected on new domain', 'Sofia Rinaldi', 'Chloe Martin', 2, 2, 'Licensing', '2026-09-17 09:31:00', 8, 'We moved the site to a new domain and the key now says it is not valid for this host.', 'Keys are tied to the domain. I can add the new host if you tell me whether the old one should be removed.', '', NULL),
('TCK-1038', 'How do I export the customer list?', 'Oliver Grant', 'Jonas Weber', 4, 3, 'How-to', '2026-09-17 14:20:00', 48, 'I need all customers as a spreadsheet for our accountant. Where is the export?', 'Open Customers, apply any filter you need and press the Excel button above the list.', 'Explained the Excel export. Customer confirmed the file opened correctly.', 5),
('TCK-1039', 'Cannot log in after password reset', 'Hannah Ortiz', 'Ben Carter', 2, 1, 'Account', '2026-09-18 08:03:00', 8, 'The reset e-mail arrives but the link says it has expired. I tried three times.', 'The mail server delayed the messages by about 20 minutes, so the links expired. Sending you a fresh one now.', '', NULL),
('TCK-1040', 'Invoice shows the wrong VAT number', 'Peter Lindgren', 'Amara Singh', 3, 2, 'Billing', '2026-09-18 10:15:00', 24, 'Our VAT number on the latest invoice has a typo. Can you issue a corrected one?', 'Sure. Could you confirm the exact number and the billing address you want on the credit note?', '', NULL),
('TCK-1041', 'Checkout page shows a blank screen', 'Marta Delgado', 'Laura Vidal', 1, 1, 'Bug', '2026-09-19 16:42:00', 4, 'Since this morning customers see a white page after pressing Pay. We are losing orders.', 'Reproduced on the staging copy. The payment script fails after the last update; a rollback is being prepared.', '', NULL);
