-- List Manager example: Help Desk Tickets
-- Run this file in phpMyAdmin (or the mysql client) on your Joomla database, then import the
-- configuration file in Components > List Manager > Import. The table name has no Joomla prefix.
DROP TABLE IF EXISTS `lm_tickets`;
CREATE TABLE `lm_tickets` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `ticket_no` varchar(12) NOT NULL,
  `subject` varchar(160) NOT NULL,
  `requester` varchar(80) NOT NULL,
  `agent` varchar(60) NOT NULL,
  `priority` tinyint(4) NOT NULL DEFAULT 3,
  `status` tinyint(4) NOT NULL DEFAULT 1,
  `category` varchar(20) NOT NULL DEFAULT '',
  `created` datetime NOT NULL,
  `sla_hours` smallint(6) NOT NULL DEFAULT 24,
  `message` text,
  `reply` text,
  `resolution` text,
  `satisfaction` tinyint(4) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

